 css='''body{margin:0;background:#f3f6f9;color:#182a3a;font:16px/1.75 system-ui,sans-serif}header{background:#102d45;color:white;padding:52px max(24px,calc((100vw - 1040px)/2))}header p{color:#c8deed}h1{font-size:clamp(28px,4vw,45px);line-height:1.25}main{max-width:1040px;margin:auto;padding:24px}section{background:white;padding:28px 32px;margin:22px 0;border:1px solid #dce5ec;border-radius:12px}h2{font-size:25px;line-height:1.4}p{max-width:95ch}pre{background:#edf3f7;border-left:4px solid #1676b8;padding:18px;overflow:auto;font:14px/1.7 ui-monospace,monospace}nav{display:flex;flex-wrap:wrap;gap:16px}a{color:inherit}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:10px;text-align:left;border-bottom:1px solid #dce5ec}th{background:#edf3f7}.scroll{overflow:auto}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.cards div{background:#edf5fa;padding:18px}.cards strong{display:block;font-size:30px;color:#075786}.cards span{font-size:13px}svg{width:100%;height:auto;background:white}svg text{font:12px system-ui;fill:#4b6070}.legend{display:flex;gap:24px;font-size:13px}.record{padding:16px 0;border-bottom:1px solid #dce5ec}summary{cursor:pointer;font-weight:600}small{font-weight:normal;color:#536979}input{padding:12px;width:min(90%,450px);font:inherit;border:1px solid #a9becd;border-radius:5px}.hash{font:12px/1.6 monospace;overflow-wrap:anywhere;color:#536979}@media(max-width:600px){section{padding:18px}main{padding:8px}.cards{grid-template-columns:1fr}}@media print{header{padding:20px}section{break-inside:avoid}input{display:none}body{background:white}}'''
